// ============================================================================
// PCIe_apb: APB4 register wrapper around PCIe_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/PCIe.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/PCIe.md
// ============================================================================
module PCIe_apb #(
  parameter int MAXLEN    = 32,
  // bytes in a TLP
  parameter int TXN       = 4,
  // unacknowledged TLPs (power of 2)
  parameter int RXN       = 4,
  // TLPs in the receive buffer (power of 2)
  parameter int REPLAY_TO = 600,
  // replay timer, clocks
  parameter int FC_GAP    = 32,
  // InitFC repeat, clocks
  parameter int UPD_GAP   = 1024
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [7:0] tx_sym,
  output logic tx_k,
  input logic [7:0] rx_sym,
  input logic rx_k
);
  localparam logic [31:0] ID_VALUE = 32'h50430200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [8:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd9) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_link_up;
  logic          c_tlp_valid;
  logic          c_tlp_ready;
  logic [7:0]    c_tlp_data;
  logic          c_tlp_last;
  logic          c_rx_valid;
  logic          c_rx_ready;
  logic [7:0]    c_rx_data;
  logic          c_rx_last;
  logic          c_dl_up;
  logic          c_retrain;
  logic          c_ev_tlp_bad;
  logic          c_ev_tlp_seq;
  logic          c_ev_tlp_dup;
  logic          c_ev_tlp_null;
  logic          c_ev_overflow;
  logic          c_ev_dllp_bad;
  logic          c_ev_dllp_proto;
  logic          c_ev_frame;
  logic          c_ev_nak;
  logic          c_ev_replay;
  PCIe_top #(.MAXLEN(MAXLEN), .TXN(TXN), .RXN(RXN), .REPLAY_TO(REPLAY_TO), .FC_GAP(FC_GAP), .UPD_GAP(UPD_GAP)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .link_up(c_link_up),
    .tx_sym(tx_sym),
    .tx_k(tx_k),
    .rx_sym(rx_sym),
    .rx_k(rx_k),
    .tlp_valid(c_tlp_valid),
    .tlp_ready(c_tlp_ready),
    .tlp_data(c_tlp_data),
    .tlp_last(c_tlp_last),
    .rx_valid(c_rx_valid),
    .rx_ready(c_rx_ready),
    .rx_data(c_rx_data),
    .rx_last(c_rx_last),
    .dl_up(c_dl_up),
    .retrain(c_retrain),
    .ev_tlp_bad(c_ev_tlp_bad),
    .ev_tlp_seq(c_ev_tlp_seq),
    .ev_tlp_dup(c_ev_tlp_dup),
    .ev_tlp_null(c_ev_tlp_null),
    .ev_overflow(c_ev_overflow),
    .ev_dllp_bad(c_ev_dllp_bad),
    .ev_dllp_proto(c_ev_dllp_proto),
    .ev_frame(c_ev_frame),
    .ev_nak(c_ev_nak),
    .ev_replay(c_ev_replay)
  );

  // ---------------- registers ----------------
  logic [13:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [0:0] r_CTRL;   // 12'h014 CTRL
  logic [8:0] h_TX;   // 12'h018 TX holding register
  logic [8:0] h_RX;   // 12'h01C RX holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 1'h0;
      h_TX <= '0;
      h_RX <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[13:0] & wmask[13:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[13:0]) | (PWDATA[13:0] & wmask[13:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[6] && !full_TX) h_TX <= (h_TX & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[6] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tlp_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[7]))) begin
        h_RX[7:0] <= c_rx_data[7:0];
        h_RX[8:8] <= c_rx_last;
        avail_RX <= 1'b1;
      end else if (rd && hit[7]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_link_up = r_CTRL;
  assign c_tlp_data[7:0] = h_TX[7:0];
  assign c_tlp_last = h_TX[8:8];
  assign c_tlp_valid = full_TX;
  assign c_rx_ready = ~avail_RX | (rd & hit[7]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_retrain;
    irq_set[1] = c_ev_tlp_bad;
    irq_set[2] = c_ev_tlp_seq;
    irq_set[3] = c_ev_tlp_dup;
    irq_set[4] = c_ev_tlp_null;
    irq_set[5] = c_ev_overflow;
    irq_set[6] = c_ev_dllp_bad;
    irq_set[7] = c_ev_dllp_proto;
    irq_set[8] = c_ev_frame;
    irq_set[9] = c_ev_nak;
    irq_set[10] = c_ev_replay;
    irq_set[11] = full_TX & c_tlp_ready;
    irq_set[12] = wr & (hit[6]) & full_TX;
    irq_set[13] = c_rx_valid & (~avail_RX | (rd & hit[7]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(h_TX);
      10'd7: apb_rdata = 32'(h_RX);
      10'd8: apb_rdata = 32'({c_dl_up});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
